<?php
require_once __DIR__ . '/_bootstrap.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
$product=b2cRows("SELECT p.*,c.name category_name,COALESCE(i.quantity-i.reserved_quantity,0) available_quantity,(SELECT pi.image FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.is_primary DESC,pi.sort_order LIMIT 1) image FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN inventory i ON i.product_id=p.id AND i.variant_id IS NULL WHERE p.id=? AND p.status='active' LIMIT 1",[$id])[0]??null;
if(!$product){http_response_code(404);b2cPage('Product not found');?><div class="empty"><h2>Product not found</h2><p>This item may have been removed or is no longer available.</p><a class="btn" href="products.php">Back to products</a></div><?php b2cEnd();exit;}
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken();$qty=max(1,min(99,(int)($_POST['quantity']??1)));if(!isLoggedIn()||currentRole()!=='customer'){redirect(BASE_URL.'/login.php?role=customer');}elseif(!$b2cDb){$error='Cart is temporarily unavailable.';}else{try{$s=$b2cDb->prepare('INSERT INTO cart_items (user_id,product_id,quantity) VALUES (?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)');$s->execute([(int)currentUserId(),$id,$qty]);$notice='Added to your cart.';}catch(Throwable $e){$error='We could not update your cart. Please try again.';}}}
b2cPage($product['name']);
?>
<?php if($notice): ?><div class="alert"><?= e($notice) ?> <a href="cart.php"><strong>View cart →</strong></a></div><?php endif; ?><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<div class="detail"><div class="detail-image"><?php if($product['image']): ?><img src="<?= e(b2cImage($product['image'])) ?>" alt="<?= e($product['name']) ?>"><?php else: ?>✦<?php endif; ?></div><div><span class="eyebrow"><?= e($product['category_name']??'Collection') ?></span><h1><?= e($product['name']) ?></h1><p class="price"><?= e(formatPrice($product['retail_price'])) ?></p><p><?= nl2br(e($product['description']??'A quality product from a trusted Quincy Store seller.')) ?></p><p class="muted"><?= ((int)$product['available_quantity']>0) ? 'In stock · Ships soon' : 'Currently out of stock' ?></p><?php if((int)$product['available_quantity']>0): ?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label>Quantity <input class="qty" type="number" name="quantity" min="1" max="<?= max(1,(int)$product['available_quantity']) ?>" value="1"></label><button class="btn gold" type="submit">Add to cart</button></form><?php else: ?><button class="btn light" disabled>Out of stock</button><?php endif; ?></div></div>
<?php b2cEnd(); ?>